//! @title Modular Groups & Euler's Totient
//! @chapter 31.3 (1e–4e)
//! @editions 1,2,3,4
//! @summary The group Z_n*, Euler's φ(n), subgroups generated by an element, and Euler's/Fermat's theorems.
//! @order 60
use super::euclid_gcd::gcd;
use super::modular_exponentiation::{mod_pow, order};
use crate::outln;

/// Elements of the multiplicative group Z_n* = { a : 0 < a < n, gcd(a, n) = 1 }.
pub fn units(n: u64) -> Vec<u64> { (1..n.max(2)).filter(|&a| gcd(a, n) == 1).collect() }

/// Euler's phi function from the prime factorisation: φ(n) = n Π_{p|n} (1 − 1/p).
pub fn totient(mut n: u64) -> u64 {
    let mut phi = n;
    let mut p = 2;
    while p * p <= n {
        if n % p == 0 {
            while n % p == 0 { n /= p; }
            phi -= phi / p;
        }
        p += 1;
    }
    if n > 1 { phi -= phi / n; }
    phi
}

/// The subgroup ⟨a⟩ = {a⁰, a¹, …} of Z_n* generated by a.
pub fn subgroup(a: u64, n: u64) -> Vec<u64> {
    let mut s = vec![1 % n];
    let mut x = a % n;
    while x != 1 % n { s.push(x); x = (x as u128 * a as u128 % n as u128) as u64; }
    s
}

pub fn is_primitive_root(g: u64, n: u64) -> bool { order(g, n) == Some(totient(n)) }

pub fn demo() -> String {
    let mut o = String::new();
    outln!(o, "Z_15* = {:?}  (φ(15) = {})", units(15), totient(15));
    outln!(o, "subgroup <2> of Z_15* = {:?}  (order {}, divides φ(15) = 8: Lagrange)", subgroup(2, 15), subgroup(2, 15).len());
    outln!(o, "subgroup <7> of Z_15* = {:?}", subgroup(7, 15));
    outln!(o, "φ(n) for n = 1..12: {:?}", (1..=12).map(totient).collect::<Vec<_>>());
    outln!(o, "Euler's theorem check: 7^φ(15) mod 15 = {}", mod_pow(7, totient(15), 15));
    let roots: Vec<u64> = (1..13).filter(|&g| is_primitive_root(g, 13)).collect();
    outln!(o, "primitive roots mod 13: {:?} ({} = φ(φ(13)))", roots, totient(totient(13)));
    o
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn totient_counts_units() {
        for n in 2..300 { assert_eq!(totient(n) as usize, units(n).len(), "n={n}"); }
        assert_eq!(totient(1), 1);
    }
    #[test]
    fn lagrange_and_euler() {
        for n in 2..80u64 {
            let phi = totient(n);
            for a in units(n) {
                assert_eq!(phi % subgroup(a, n).len() as u64, 0, "subgroup order must divide φ(n)");
                assert_eq!(mod_pow(a, phi, n), 1);
            }
        }
    }
    #[test]
    fn primitive_root_counts() {
        // for prime p there are φ(p−1) primitive roots
        for p in [3u64, 5, 7, 11, 13, 17, 19, 23] {
            assert_eq!((1..p).filter(|&g| is_primitive_root(g, p)).count() as u64, totient(p - 1));
        }
        assert!(!(1..15).any(|g| is_primitive_root(g, 15))); // Z_15* is not cyclic
    }
}
